/*!
 * Themeasy — Elementor Editor Helpers
 *
 * Provides helper functions for Elementor editor integration.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window) {
  'use strict';

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {};

  // ------------------------------------------------------------------------
  // Helper Functions
  // ------------------------------------------------------------------------

  /**
   * Escapes a raw string for use inside a quoted HTML attribute.
   *
   * Parity with PHP esc_attr() (ENT_QUOTES — both quote styles escaped, so
   * single-quoted attribute output is safe too). `&` must be escaped first so
   * the entities emitted by the later replacements are not re-encoded.
   * Browsers decode these entities in getAttribute(), so JSON payloads
   * round-trip intact.
   *
   * @param {*} value - Raw key or value (unescaped input only).
   * @returns {string} Entity-escaped string.
   */
  function escapeAttribute(value) {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  /**
   * Builds HTML attributes from an object.
   *
   * Values are entity-escaped for double-quoted attribute output (esc_attr()
   * parity) — pass raw, unescaped values. Names are normalized to a safe
   * subset (alphanumerics, colon, underscore, hyphen): browsers do not decode
   * entities in attribute-name position, so escaping cannot stop a hostile
   * name from splitting the attribute — stripping can. Mirrors
   * themeasy_html_attributes() in PHP.
   *
   * @param {Object} attributes - Key-value pairs of attributes.
   * @returns {string} HTML attributes as a string.
   */
  window.Themeasy.htmlAttributes = function(attributes) {
    if (!attributes || typeof attributes !== 'object') {
      return '';
    }

    let attrString = '';

    for (const key in attributes) {
      if (Object.hasOwn(attributes, key) && attributes[key] !== '' && attributes[key] !== null) {
        const attrKey = String(key).replace(/[^a-z0-9:_-]/gi, '');
        if (!attrKey) {
          continue;
        }
        const attrValue = escapeAttribute(attributes[key]);
        attrString += ` ${attrKey}="${attrValue}"`;
      }
    }

    return attrString.trim();
  };

  // ------------------------------------------------------------------------
  // Inline HTML sanitizer (editor preview)
  // ------------------------------------------------------------------------

  /**
   * Attributes every allowed tag accepts, mirroring $global_attrs in
   * themeasy_get_kses_allowed_tags(). A `style` value is filtered by
   * safeCssText() below — the twin of WordPress core's safecss_filter_attr().
   */
  const SANITIZE_GLOBAL_ATTRS = ['class', 'style'];

  /**
   * Adds the global attributes to a per-tag map, so each entry below only
   * lists what is EXTRA to them (PHP parity: the foreach that closes
   * themeasy_get_kses_allowed_tags()).
   *
   * @param {Object} tags - Map of tag name to extra allowed attribute names.
   * @returns {Object} Map of tag name to its full allowed attribute list.
   */
  function withGlobalAttrs(tags) {
    const merged = {};

    Object.keys(tags).forEach(function (tag) {
      merged[tag] = SANITIZE_GLOBAL_ATTRS.concat(tags[tag]);
    });

    return merged;
  }

  /**
   * Allowed tags/attributes for sanitizeInlineHtml(), mirroring the defaults
   * of themeasy_get_kses_allowed_tags() in PHP ('inline' context). The
   * server-side themeasy/kses_allowed_tags filter is intentionally NOT
   * mirrored: the preview sanitizer stays on the unfiltered baseline, which
   * can only make the preview stricter than the frontend, never looser.
   */
  const SANITIZE_INLINE_TAGS = withGlobalAttrs({
    mark: [],
    b: [],
    strong: [],
    em: [],
    i: [],
    u: [],
    del: [],
    s: [],
    sub: [],
    sup: [],
    small: [],
    span: [],
    br: [],
    wbr: [],
    a: ['href', 'title', 'target', 'rel', 'aria-label']
  });

  /** The 'rich' context adds paragraphs + simple lists (PHP parity). */
  const SANITIZE_RICH_TAGS = Object.assign({}, SANITIZE_INLINE_TAGS, withGlobalAttrs({
    p: [],
    div: [],
    ul: [],
    ol: [],
    li: []
  }));

  // Scheme allow-list for href values (esc_url() spirit): anything that does
  // not clearly match a safe scheme is dropped rather than escaped.
  const SANITIZE_SAFE_URL = /^(https?:|mailto:|tel:|\/|#)/i;

  // ------------------------------------------------------------------------
  // Inline CSS sanitizer (editor preview)
  // ------------------------------------------------------------------------

  /**
   * Property allow-list for safeCssText(), mirroring the `safe_style_css`
   * defaults of safecss_filter_attr() in wp-includes/kses.php (WP 7.1).
   *
   * Same asymmetry as the tag map: a property WordPress adds upstream only
   * makes the preview stricter than the frontend, which is the safe direction.
   * tests/kses-style-css-drift.php therefore fails only when this list holds
   * something core does NOT — i.e. when the preview would paint CSS that
   * wp_kses() strips on save.
   *
   * `--*` is the sentinel core uses to switch custom properties on; it is kept
   * verbatim so the drift test can compare the two lists literally.
   */
  const SAFE_CSS_PROPS = [
    'background', 'background-color', 'background-image', 'background-position',
    'background-repeat', 'background-size', 'background-attachment', 'background-blend-mode',
    'border', 'border-radius', 'border-width', 'border-color', 'border-style', 'border-right',
    'border-right-color', 'border-right-style', 'border-right-width', 'border-bottom',
    'border-bottom-color', 'border-bottom-left-radius', 'border-bottom-right-radius',
    'border-bottom-style', 'border-bottom-width', 'border-left', 'border-left-color',
    'border-left-style', 'border-left-width', 'border-top', 'border-top-color',
    'border-top-left-radius', 'border-top-right-radius', 'border-top-style', 'border-top-width',
    'border-spacing', 'border-collapse', 'caption-side', 'columns', 'column-count',
    'column-fill', 'column-gap', 'column-rule', 'column-span', 'column-width', 'display',
    'color', 'filter', 'font', 'font-family', 'font-size', 'font-style', 'font-variant',
    'font-weight', 'letter-spacing', 'line-height', 'text-align', 'text-decoration',
    'text-indent', 'text-transform', 'white-space', 'height', 'min-height', 'max-height',
    'width', 'min-width', 'max-width', 'margin', 'margin-right', 'margin-bottom', 'margin-left',
    'margin-top', 'margin-block-start', 'margin-block-end', 'margin-inline-start',
    'margin-inline-end', 'padding', 'padding-right', 'padding-bottom', 'padding-left',
    'padding-top', 'padding-block-start', 'padding-block-end', 'padding-inline-start',
    'padding-inline-end', 'flex', 'flex-basis', 'flex-direction', 'flex-flow', 'flex-grow',
    'flex-shrink', 'flex-wrap', 'gap', 'row-gap', 'grid-template-columns', 'grid-auto-columns',
    'grid-column-start', 'grid-column-end', 'grid-column', 'grid-column-gap',
    'grid-template-rows', 'grid-auto-rows', 'grid-row-start', 'grid-row-end', 'grid-row',
    'grid-row-gap', 'grid-gap', 'justify-content', 'justify-items', 'justify-self',
    'align-content', 'align-items', 'align-self', 'clear', 'cursor', 'direction', 'float',
    'list-style-type', 'object-fit', 'object-position', 'opacity', 'overflow', 'vertical-align',
    'writing-mode', 'position', 'top', 'right', 'bottom', 'left', 'z-index', 'box-shadow',
    'aspect-ratio', 'container-type', 'fill', 'fill-opacity', 'fill-rule', 'stroke',
    'stroke-dasharray', 'stroke-dashoffset', 'stroke-linecap', 'stroke-linejoin',
    'stroke-miterlimit', 'stroke-opacity', 'stroke-width', 'color-interpolation',
    'color-interpolation-filters', 'paint-order', 'stop-color', 'stop-opacity', 'flood-color',
    'flood-opacity', 'lighting-color', 'marker', 'marker-end', 'marker-mid', 'marker-start',
    'clip-path', 'clip-rule', 'mask', 'mask-type', 'cx', 'cy', 'r', 'rx', 'ry', 'x', 'y', 'd',
    'alignment-baseline', 'baseline-shift', 'dominant-baseline', 'glyph-orientation-horizontal',
    'glyph-orientation-vertical', 'text-anchor', 'unicode-bidi', 'word-spacing',
    'font-size-adjust', 'font-stretch', 'color-rendering', 'image-rendering', 'shape-rendering',
    'text-rendering', 'vector-effect', 'transform', 'transform-origin', 'pointer-events',
    'visibility', '--*'
  ];

  // Properties whose value may legitimately carry a url() token. Per the CSS
  // spec, and unrelated to the allow-list above (core keeps the two apart too).
  const SAFE_CSS_URL_PROPS = [
    'background', 'background-image', 'cursor', 'filter', 'list-style', 'list-style-image',
    'clip-path', 'fill', 'marker', 'marker-end', 'marker-mid', 'marker-start', 'mask', 'stroke'
  ];

  // Properties whose value may carry a *-gradient() token.
  const SAFE_CSS_GRADIENT_PROPS = ['background', 'background-image'];

  // A custom property assignment (`--brand-ink: #f43d00`).
  const CSS_CUSTOM_PROP = /^--[a-zA-Z0-9-_]+$/;

  // A url() token, and the quoted-or-bare target inside one.
  const CSS_URL_TOKEN = /url\([^)]+\)/g;
  const CSS_URL_TARGET = /^url\(\s*(['"]?)([\s\S]*)\1\s*\)$/;

  // A *-gradient() token, allowing one level of nested functions (rgb(), var()).
  const CSS_GRADIENT_TOKEN = /(?:repeating-)?(?:linear|radial|conic)-gradient\((?:[^()]|\([^()]*\))*\)/g;

  // Opening of a value function core recognizes: general purpose, transforms,
  // and the basic shapes used by clip-path.
  const CSS_FUNCTION_OPEN = new RegExp(
    '\\b(?:'
      + 'var|calc|min|max|minmax|clamp|repeat'
      + '|matrix|matrix3d|perspective'
      + '|rotate|rotate3d|rotateX|rotateY|rotateZ'
      + '|scale|scale3d|scaleX|scaleY|scaleZ'
      + '|skew|skewX|skewY'
      + '|translate|translate3d|translateX|translateY|translateZ'
      + '|circle|ellipse|inset|path|polygon|rect|shape|xywh'
    + ')\\(',
    'g'
  );

  // What may never survive in a declaration once the recognized functions and
  // the url()/gradient tokens have been lifted out of it.
  const CSS_UNSAFE_CHARS = /[\\(&=}]|\/\*/;

  /**
   * Whether a url() target is safe to resolve from a preview stylesheet.
   *
   * Core validates the same token with wp_kses_bad_protocol() against
   * wp_allowed_protocols(); this positive test accepts a strict subset of that
   * list plus scheme-less relative paths, so the preview stays the stricter of
   * the two. The C0 strip mirrors esc_url() and Themeasy.safeUrl(): a browser
   * removes those characters before it parses the scheme.
   *
   * @param {string} url - Raw target from inside a url() token.
   * @returns {boolean} True when the target may be kept.
   */
  function isSafeCssUrl(url) {
    const probe = String(url).replace(URL_CONTROL_CHARS, '').trim();

    if (probe === '') {
      return false;
    }

    // No scheme at all means a relative path — there is nothing to smuggle.
    return SANITIZE_SAFE_URL.test(probe) || !/^[a-z][a-z0-9+.-]*:/i.test(probe);
  }

  /**
   * Lifts every recognized value function out of a declaration, parentheses
   * included, so what remains can be tested for stray syntax.
   *
   * Core does this with a recursive PCRE pattern; JS has no recursion, so the
   * matching close parenthesis is found by counting depth — same result for
   * nested calls (`translate(calc(1px + 2px))`) and for a recognized function
   * wrapping an unrecognized one (`var(--x, rgb(0,0,0))`).
   *
   * @param {string} declaration - One `property: value` declaration.
   * @returns {string} The declaration with those functions removed.
   */
  function stripCssFunctions(declaration) {
    let result = declaration;
    let match;

    CSS_FUNCTION_OPEN.lastIndex = 0;

    while ((match = CSS_FUNCTION_OPEN.exec(result)) !== null) {
      const open = match.index + match[0].length - 1;
      let depth = 0;
      let close = -1;

      for (let i = open; i < result.length; i++) {
        if (result[i] === '(') {
          depth++;
        } else if (result[i] === ')') {
          depth--;

          if (depth === 0) {
            close = i;
            break;
          }
        }
      }

      // Unbalanced: leave it in place. The stray "(" fails the test below,
      // exactly as core's non-matching pattern does.
      if (close === -1) {
        break;
      }

      result = result.slice(0, match.index) + result.slice(close + 1);
      CSS_FUNCTION_OPEN.lastIndex = 0;
    }

    return result;
  }

  /**
   * Sanitizes an inline `style` attribute for the editor preview.
   *
   * JS twin of safecss_filter_attr() in wp-includes/kses.php — the filter
   * wp_kses() itself runs on every style attribute it keeps. Declarations are
   * taken one by one: the property must be allow-listed (or be a custom
   * property), a url() target must survive the scheme check, and whatever is
   * left of the declaration once the recognized functions and url()/gradient
   * tokens are lifted out must be free of the characters core rejects.
   *
   * Exposed on the namespace so a content_template() that builds a style
   * attribute out of a free-text setting can reuse it. The result is safe as
   * an attribute VALUE only — concatenating it into an attribute string still
   * needs _.escape() or htmlAttributes().
   *
   * @param {*} css - Raw style attribute value (already entity-decoded by the
   *   DOM parser, matching core's WP_HTML_Decoder step).
   * @returns {string} The surviving declarations, or '' when none survive.
   */
  window.Themeasy.safeCssText = function (css) {
    if (css === null || css === undefined) {
      return '';
    }

    // wp_kses_no_null() plus the newline/tab strip core opens with.
    const declarations = String(css).replace(/\0/g, '').replace(/[\n\r\t]/g, '').split(';');
    const safe = [];

    declarations.forEach(function (declaration) {
      const item = declaration.trim();
      const separator = item.indexOf(':');

      // Empty fragment, or one with no value at all (core keeps the latter;
      // dropping it is the stricter direction).
      if (item === '' || separator === -1) {
        return;
      }

      // Property names are compared verbatim: core's in_array() is
      // case-sensitive, so `COLOR:` is dropped there too.
      const property = item.slice(0, separator).trim();
      const value = item.slice(separator + 1).trim();
      const isCustomProp = CSS_CUSTOM_PROP.test(property);

      if (!isCustomProp && SAFE_CSS_PROPS.indexOf(property) === -1) {
        return;
      }

      // An allow-listed property is typed by its name, a custom one by its value.
      const hasUrl = isCustomProp
        ? value.indexOf('url(') === 0
        : SAFE_CSS_URL_PROPS.indexOf(property) !== -1;
      const hasGradient = isCustomProp
        ? value.indexOf('-gradient(') !== -1
        : SAFE_CSS_GRADIENT_PROPS.indexOf(property) !== -1;

      let test = item;

      if (hasUrl) {
        const tokens = value.match(CSS_URL_TOKEN) || [];

        for (let i = 0; i < tokens.length; i++) {
          const target = CSS_URL_TARGET.exec(tokens[i]);

          if (!target || !isSafeCssUrl(target[2])) {
            return;
          }

          test = test.replace(tokens[i], '');
        }
      }

      if (hasGradient) {
        test = test.replace(CSS_GRADIENT_TOKEN, '');
      }

      if (!CSS_UNSAFE_CHARS.test(stripCssFunctions(test))) {
        safe.push(item);
      }
    });

    return safe.join(';');
  };

  /**
   * Recursively sanitizes the children of a node against an allowed-tags map.
   *
   * Disallowed elements are unwrapped (tag stripped, sanitized children kept
   * — wp_kses behavior); comments and other non-element nodes are removed;
   * attributes outside the per-tag allow-list are stripped; href values must
   * match the scheme allow-list or the attribute is removed; style values are
   * filtered declaration by declaration and the attribute is removed when
   * nothing survives.
   *
   * @param {Node} parent - Element or fragment whose children get sanitized.
   * @param {Object} allowedTags - Map of tag name to allowed attribute names.
   */
  function sanitizeDomChildren(parent, allowedTags) {
    const children = Array.prototype.slice.call(parent.childNodes);

    children.forEach(function (node) {
      // Text nodes are inert content — keep.
      if (node.nodeType === 3) {
        return;
      }

      // Comments, CDATA, processing instructions — drop (wp_kses parity).
      if (node.nodeType !== 1) {
        parent.removeChild(node);
        return;
      }

      // Sanitize the subtree first so unwrapped children are already clean.
      sanitizeDomChildren(node, allowedTags);

      const tag = node.tagName.toLowerCase();

      if (!Object.hasOwn(allowedTags, tag)) {
        while (node.firstChild) {
          parent.insertBefore(node.firstChild, node);
        }
        parent.removeChild(node);
        return;
      }

      const allowedAttrs = allowedTags[tag];
      const attributes = Array.prototype.slice.call(node.attributes);

      attributes.forEach(function (attribute) {
        const name = attribute.name.toLowerCase();

        if (allowedAttrs.indexOf(name) === -1) {
          node.removeAttribute(attribute.name);
          return;
        }

        if (name === 'href' && !SANITIZE_SAFE_URL.test(String(attribute.value).trim())) {
          node.removeAttribute(attribute.name);
          return;
        }

        if (name === 'style') {
          const declarations = window.Themeasy.safeCssText(attribute.value);

          if (declarations === '') {
            node.removeAttribute(attribute.name);
          } else if (declarations !== attribute.value) {
            node.setAttribute(attribute.name, declarations);
          }
        }
      });
    });
  }

  /**
   * Sanitizes user-authored text for raw ({{{ }}}) editor-preview output.
   *
   * JS twin of `wp_kses( $text, themeasy_get_kses_allowed_tags( $context ) )`:
   * parses into an inert <template> (nothing executes or loads), strips every
   * tag/attribute outside the allow-list and returns serialized HTML. Route
   * every free-text setting (titles, eyebrows, descriptions, button labels)
   * through this before concatenating into HTML strings in content_template().
   *
   * The result is safe as ELEMENT CONTENT only — values placed inside
   * attribute strings must still go through _.escape() or htmlAttributes().
   *
   * @param {*} html - Raw setting value.
   * @param {string} [context] - 'inline' (default) or 'rich' (adds p/div/ul/ol/li).
   * @returns {string} Sanitized HTML string.
   */
  window.Themeasy.sanitizeInlineHtml = function (html, context) {
    if (html === null || html === undefined || html === '') {
      return '';
    }

    const value = String(html);

    // Fast path: plain text with nothing tag-like is inert element content.
    if (value.indexOf('<') === -1) {
      return value;
    }

    const allowedTags = (context === 'rich') ? SANITIZE_RICH_TAGS : SANITIZE_INLINE_TAGS;
    const template = document.createElement('template');

    template.innerHTML = value;
    sanitizeDomChildren(template.content, allowedTags);

    return template.innerHTML;
  };

  // ------------------------------------------------------------------------
  // URL scheme guard (editor preview)
  // ------------------------------------------------------------------------

  // Schemes that run script when a browser resolves them.
  const UNSAFE_URL_SCHEME = /^\s*(javascript|vbscript|data):/i;

  // The FULL C0 control range. Per the URL spec a browser removes every C0
  // control (U+0000-U+001F) from a URL before parsing its scheme, so both
  // "java<TAB>script:" and a leading NUL resolve as javascript: — and NUL is
  // matched by neither \s nor [\t\n\r], which is why the narrower strip this
  // replaced was bypassable. Keep this range in sync with esc_url() (PHP
  // strips the same characters server-side, which is why render() is immune).
  // eslint-disable-next-line no-control-regex
  const URL_CONTROL_CHARS = /[\x00-\x1f]/g;

  /**
   * Drops a URL whose scheme would execute script in the editor preview.
   *
   * content_template() has no add_link_attributes() / esc_url(), and `{{ }}`
   * only entity-escapes — it does NOT block a javascript:/vbscript:/data: URL.
   * Route every href/src built from a setting through this before it reaches
   * the markup, or a hostile Link field becomes stored XSS against the next
   * editor who opens the post.
   *
   * The scheme is tested against a control-char-stripped COPY; the original
   * value is returned when it passes, so legitimate URLs round-trip intact.
   * A value that fails returns '' — callers should treat that as "no link".
   *
   * The result is safe as an href/src VALUE only: values concatenated into an
   * attribute string still need _.escape() or htmlAttributes() (this guard
   * does not strip embedded quotes).
   *
   * @param {*} url - Raw URL from a setting.
   * @returns {string} The URL, or '' when its scheme is unsafe.
   */
  window.Themeasy.safeUrl = function (url) {
    if (url === null || url === undefined) {
      return '';
    }

    const value = String(url);

    return UNSAFE_URL_SCHEME.test(value.replace(URL_CONTROL_CHARS, '')) ? '' : value;
  };

  /**
   * Builds a CSS url() token from an Elementor MEDIA control value.
   *
   * Editor-side mirror of themeasy_media_css_url() in core/helpers.php. A MEDIA
   * control's URL must never be bound into a control's `selectors` array: with
   * an empty attachment id (Elementor's "Insert from URL" flow) the raw string
   * reaches the generated stylesheet and can break out of the declaration.
   * A positive scheme allowlist stands in for esc_url_raw(), and the character
   * strip closes the quoted-token breakout.
   *
   * @param {Object} media - MEDIA control value ({ id, url }).
   * @returns {string} A `url("…")` token, or '' when no usable image is set.
   */
  window.Themeasy.mediaCssUrl = function (media) {
    if (!media || typeof media !== 'object') return '';

    let url = String(media.url || '').replace(/^\s+|\s+$/g, '');

    if (!/^(https?:|\/\/|\/)/i.test(url)) return '';

    url = url.replace(/["'()\\]/g, '');

    return url === '' ? '' : 'url("' + url + '")';
  };

  /**
   * Collapses an Elementor responsive control into the
   * "desktop,laptop,tablet,mobile" CSV the slider module reads.
   *
   * Mirrors themeasy_slider_responsive_csv() in PHP: an empty breakpoint
   * inherits the previous (wider) one, the same cascade the editor shows.
   *
   * @param {Object} settings - The widget settings object.
   * @param {string} control - Base control key.
   * @param {number} fallback - Value used when the desktop slot is empty.
   * @returns {string} e.g. '25,25,8,8'
   */
  window.Themeasy.sliderResponsiveCsv = function (settings, control, fallback) {
    const values = [];
    let previous = fallback;

    ['', '_laptop', '_tablet', '_mobile'].forEach(function (suffix) {
      const setting = settings ? settings[control + suffix] : null;
      const size = setting ? setting.size : null;

      if (size !== null && size !== undefined && size !== '' && isFinite(size)) {
        previous = parseFloat(size);
      }

      values.push(previous);
    });

    return values.join(',');
  };

  /**
   * Builds a responsive column class for Bootstrap based on the number of columns.
   *
   * @param {number} columns - The number of columns (1-12).
   * @param {Object<string, number>} [caps] - Optional breakpoint => column cap
   *   map, narrowest first (themeasy_bootstrap_columns() parity).
   * @returns {string} Bootstrap column class.
   */
  window.Themeasy.bootstrapColumns = function(columns, caps) {
    columns = Math.max(1, Math.min(12, parseInt(columns)));

    const breakpoints = (caps && Object.keys(caps).length) ? caps : {
      xs: 2,
      sm: 4,
      md: 6,
      lg: 8,
      xl: 10,
      xxl: 12
    };

    let baseClass = 'row row-cols-1';

    if (columns === 1) {
      return baseClass;
    }

    for (const bp in breakpoints) {
      const colCount = breakpoints[bp];
      baseClass += ' row-cols-' + bp + '-' + (columns >= colCount ? colCount : columns);
      if (columns <= colCount) break;
    }

    return baseClass;
  };

  /**
   * Normalize an Elementor icon setting and apply a fallback.
   *
   * Elementor may not hydrate the default icon into `settings` on the first
   * render, so we guarantee a valid icon object for renderIcon().
   *
   * Supports:
   * - New format: { value: 'fas fa-star', library: 'solid' }
   * - Old format: 'fas fa-star'
   *
   * @param {*} iconSetting
   * @param {Object|null} fallbackIcon
   * @returns {Object|null}
   */
  window.Themeasy.normalizeIconSetting = function (iconSetting, fallbackIcon) {
    // New format.
    if (iconSetting && typeof iconSetting === 'object' && iconSetting.value) {
      return iconSetting;
    }

    // Old format string: "fas fa-star".
    if (typeof iconSetting === 'string' && iconSetting) {
      return {
        value: iconSetting,
        library: (fallbackIcon && fallbackIcon.library) ? fallbackIcon.library : 'solid'
      };
    }

    // Not hydrated yet -> fallback.
    if (fallbackIcon && fallbackIcon.value) {
      return fallbackIcon;
    }

    return null;
  };

  /**
   * Merge the icon-contract SVG normalization into caller attributes.
   *
   * Mirrors themeasy_get_icon_svg_normalization() in PHP: the root <svg> of
   * every inline icon is pinned to width/height="1em" so the glyph tracks the
   * icon wrapper's font-size, while any CSS (widget rules or Elementor
   * control output) still overrides it — presentation attributes lose to
   * every stylesheet rule. Caller attributes win over the defaults.
   *
   * @param {Object|null} attrs - Caller attributes for the root <svg>.
   * @returns {Object} Attributes with the normalization defaults merged in.
   */
  function normalizeIconSvgAttributes(attrs) {
    return Object.assign({ width: '1em', height: '1em' }, attrs || {});
  }

  /**
   * Split a themeasy-svg value into [ library, iconName ].
   *
   * Accepts:
   * - "arrow-right"          → [ 'ty-feather', 'arrow-right' ]
   * - "animated/radiant-spin" → [ 'animated', 'radiant-spin' ]
   * - "feather/arrow-right"  → [ 'ty-feather', 'arrow-right' ] (legacy shim:
   *   the feather dir became ty-feather 2026-07-22; mirrors PHP)
   *
   * @param {string} value
   * @returns {Array|null}
   */
  window.Themeasy.parseThemeasySvgValue = function (value) {
    if (typeof value !== 'string' || !value) {
      return null;
    }

    const parts   = value.indexOf('/') !== -1 ? value.split('/') : [ 'ty-feather', value ];
    let svgLib    = parts[0].replace(/[^a-z0-9_-]/gi, '');
    const svgName = parts[1].replace(/[^a-z0-9_-]/gi, '');

    if (svgLib === 'feather') {
      svgLib = 'ty-feather';
    }

    if (!svgLib || !svgName) {
      return null;
    }

    return [ svgLib, svgName ];
  };

  /**
   * Extract the icon file name from a ty-* icon picker value.
   *
   * Mirrors themeasy_parse_ty_icon_name() in PHP: the Themeasy Icons picker
   * tabs (ty-feather, ty-solar-*) store a class-shaped value
   * ("ty-solar-line-heart", or defensively any "displayPrefix prefix-name"
   * multi-token form) — keep the last token, strip the "{library}-" prefix,
   * normalize to a safe file-name subset.
   *
   * @param {string} library Library slug (e.g. 'ty-feather').
   * @param {string} value   Raw icon picker value.
   * @returns {string} Icon name without extension, or '' when unparsable.
   */
  window.Themeasy.parseTyIconName = function (library, value) {
    if (typeof library !== 'string' || library.indexOf('ty-') !== 0) {
      return '';
    }
    if (typeof value !== 'string' || !value.trim()) {
      return '';
    }

    const parts  = value.trim().split(/\s+/);
    let token    = parts[parts.length - 1];
    const prefix = library + '-';

    if (token.indexOf(prefix) === 0) {
      token = token.slice(prefix.length);
    }

    return token.replace(/[^a-z0-9_-]/gi, '');
  };

  /**
   * Resolve a ty-* library slug to its source dir under assets/media/svg/.
   *
   * Mirrors the manifest's `dir` key on the PHP side (premium libraries
   * resolve to their __premium_only-suffixed dir). The map is localized by
   * PHP as window.Themeasy.tyLibraryDirs, filtered to dirs that exist on
   * disk; missing entries fall back to the slug.
   *
   * @param {string} library Library slug (e.g. 'ty-feather').
   * @returns {string}
   */
  function resolveTyLibraryDir(library) {
    const dirs = window.Themeasy && window.Themeasy.tyLibraryDirs;
    return (dirs && typeof dirs[library] === 'string') ? dirs[library] : library;
  }

  /**
   * Build inline SVG markup for a ty-* icon from the preloaded library.
   *
   * Same contract as themeasySvgInlineMarkup(): resolves from
   * window.Themeasy.svgLibrary (preloaded by PHP) and returns '' when the
   * icon is not preloaded so callers can fall back to a remote <img>.
   *
   * @param {string} library Library slug (e.g. 'ty-feather').
   * @param {string} value   Raw icon picker value.
   * @param {Object} attrs   HTML attributes to inject into the <svg>.
   * @returns {string}
   */
  window.Themeasy.tyIconInlineMarkup = function (library, value, attrs) {
    const name = window.Themeasy.parseTyIconName(library, value);
    if (!name) {
      return '';
    }

    const dir = resolveTyLibraryDir(library);
    const preloaded = window.Themeasy && window.Themeasy.svgLibrary;
    if (!preloaded || !preloaded[dir] || typeof preloaded[dir][name] !== 'string') {
      return '';
    }

    return window.Themeasy.injectSvgAttributes(preloaded[dir][name], normalizeIconSvgAttributes(attrs));
  };

  /**
   * Build an <img> markup for a ty-* icon using the plugin assets folder.
   *
   * Fallback when the icon is not in the preloaded SVG library (mirror of
   * themeasySvgImgMarkup for the ty-* tabs).
   *
   * @param {string} library Library slug (e.g. 'ty-solar-line').
   * @param {string} value   Raw icon picker value.
   * @param {Object} attrs   HTML attributes to apply to the <img>.
   * @returns {string}
   */
  window.Themeasy.tyIconImgMarkup = function (library, value, attrs) {
    const name = window.Themeasy.parseTyIconName(library, value);
    if (!name) {
      return '';
    }

    const pluginUrl = (window.Themeasy && window.Themeasy.pluginUrl) ? window.Themeasy.pluginUrl : '';
    const src       = pluginUrl + 'assets/media/svg/' + resolveTyLibraryDir(library) + '/' + name + '.svg';
    const imgAttrs  = Object.assign({ src: src, alt: '' }, attrs || {});

    return '<img' + window.Themeasy.htmlAttributesToString(imgAttrs) + ' />';
  };

  // In-flight / failed lazy fetches for non-preloaded ty-* icons ("dir/name").
  const tyFetchPending = Object.create(null);
  const tyFetchFailed  = Object.create(null);

  /**
   * Background-fetch a ty-* icon SVG that is not in the preloaded library.
   *
   * The Solar libraries ship ~4.9k icons and are excluded from the eager
   * editor preload (manifest preload=false), so their first render falls back
   * to the transient <img>. This fetches the .svg once, caches it in
   * window.Themeasy.svgLibrary and re-renders the view, upgrading the preview
   * to the frontend-parity inline SVG (currentColor + duotone opacity work).
   * Unknown libraries (stripped premium dirs in the Free build) are ignored
   * via the tyLibraryDirs gate; failures are cached so a broken value never
   * refetches in a loop.
   *
   * @param {string} library Library slug (e.g. 'ty-solar-duotone').
   * @param {string} value   Raw icon picker value.
   * @param {Object} view    Elementor view to re-render after caching.
   */
  function requestTyIconSvg(library, value, view) {
    const name = window.Themeasy.parseTyIconName(library, value);
    const dirs = window.Themeasy && window.Themeasy.tyLibraryDirs;

    if (!name || !dirs || typeof dirs[library] !== 'string' || typeof window.fetch !== 'function') {
      return;
    }

    const dir   = dirs[library];
    const store = window.Themeasy.svgLibrary = window.Themeasy.svgLibrary || {};

    if (store[dir] && typeof store[dir][name] === 'string') {
      return;
    }

    const key = dir + '/' + name;
    if (tyFetchPending[key] || tyFetchFailed[key]) {
      return;
    }
    tyFetchPending[key] = true;

    const pluginUrl = (window.Themeasy && window.Themeasy.pluginUrl) ? window.Themeasy.pluginUrl : '';

    window.fetch(pluginUrl + 'assets/media/svg/' + dir + '/' + name + '.svg')
      .then(function (response) {
        return response.ok ? response.text() : Promise.reject(new Error(String(response.status)));
      })
      .then(function (svg) {
        if (svg.indexOf('<svg') === -1) {
          throw new Error('not an svg');
        }

        (store[dir] = store[dir] || {})[name] = svg;
        delete tyFetchPending[key];

        if (view && typeof view.render === 'function') {
          try {
            view.render();
          } catch (e) {
            // The view may have been destroyed between fetch start and end.
          }
        }
      })
      .catch(function () {
        delete tyFetchPending[key];
        tyFetchFailed[key] = true;
      });
  }

  /**
   * Inject HTML attributes into the root <svg> element.
   *
   * Mirrors themeasy_inject_svg_attributes() in PHP. The `class` attribute is
   * merged with any existing class. Other attributes replace the existing
   * value for the same name, or are appended when absent. Empty, null, false
   * and undefined values are skipped. Names are normalized to a safe subset
   * (alphanumerics, colon, underscore, hyphen); values are entity-escaped
   * (esc_attr() parity) — pass raw, unescaped values.
   *
   * @param {string} svg
   * @param {Object} attributes
   * @returns {string}
   */
  window.Themeasy.injectSvgAttributes = function (svg, attributes) {
    if (!svg || !attributes || typeof attributes !== 'object') {
      return svg || '';
    }

    const match = svg.match(/<svg\b([^>]*)>/i);
    if (!match) {
      return svg;
    }

    let existingAtts = match[1];
    let injected     = '';

    Object.keys(attributes).forEach(function (name) {
      let value = attributes[name];

      if (Array.isArray(value)) {
        value = value.join(' ');
      }
      if (value === '' || value === null || value === undefined || value === false) {
        return;
      }

      const safeName = String(name).replace(/[^a-z0-9:_-]/gi, '');
      if (!safeName) {
        return;
      }
      const safeValue = escapeAttribute(value);

      if (safeName === 'class') {
        if (existingAtts.indexOf('class="') !== -1) {
          existingAtts = existingAtts.replace(/class="([^"]*)"/, function (m, existing) {
            const trimmed = String(existing).trim();
            return 'class="' + (trimmed === '' ? safeValue : trimmed + ' ' + safeValue) + '"';
          });
        } else {
          injected += ' class="' + safeValue + '"';
        }
        return;
      }

      const pattern = new RegExp('\\s' + safeName.replace(/[-:]/g, '\\$&') + '="[^"]*"', 'i');
      if (pattern.test(existingAtts)) {
        // Function replacement: a plain replacement string would expand
        // $-sequences ($&, $', $1...) carried in the attribute value.
        existingAtts = existingAtts.replace(pattern, function () {
          return ' ' + safeName + '="' + safeValue + '"';
        });
      } else {
        injected += ' ' + safeName + '="' + safeValue + '"';
      }
    });

    // Splice by offset (substr_replace parity with PHP): String.replace would
    // expand $-sequences carried in the injected attribute values.
    const tagEnd = match.index + match[0].length;
    return svg.slice(0, match.index) + '<svg' + existingAtts + injected + '>' + svg.slice(tagEnd);
  };

  /**
   * Build inline SVG markup for a themeasy-svg icon from the preloaded library.
   *
   * The library is pre-populated by PHP via wp_add_inline_script and exposed at
   * window.Themeasy.svgLibrary. When the icon is found, the raw <svg> is returned
   * with the given attributes injected into the root tag. When the icon is not
   * in the preloaded library, returns an empty string so callers can fall back
   * to a remote <img> load.
   *
   * @param {string} value Icon reference (name or lib/name).
   * @param {Object} attrs HTML attributes to inject into the <svg>.
   * @returns {string}
   */
  window.Themeasy.themeasySvgInlineMarkup = function (value, attrs) {
    const parsed = window.Themeasy.parseThemeasySvgValue(value);
    if (!parsed) {
      return '';
    }

    const library = window.Themeasy && window.Themeasy.svgLibrary;
    if (!library || typeof library !== 'object') {
      return '';
    }

    const svgLib  = parsed[0];
    const svgName = parsed[1];

    if (!library[svgLib] || typeof library[svgLib][svgName] !== 'string') {
      return '';
    }

    return window.Themeasy.injectSvgAttributes(library[svgLib][svgName], normalizeIconSvgAttributes(attrs));
  };

  /**
   * Build an <img> markup for a themeasy-svg icon using the plugin assets folder.
   *
   * Used as a fallback when the icon is not in the preloaded SVG library (for
   * example, if a user drops a new .svg into an unknown folder at runtime).
   *
   * Accepts value forms:
   * - "arrow-right"          → ty-feather/arrow-right.svg (ty-feather is the default lib)
   * - "animated/radiant-spin" → explicit library/name form
   *
   * @param {string} value Icon reference (name or lib/name).
   * @param {Object} attrs HTML attributes to apply to the <img>.
   * @returns {string}
   */
  window.Themeasy.themeasySvgImgMarkup = function (value, attrs) {
    const parsed = window.Themeasy.parseThemeasySvgValue(value);
    if (!parsed) {
      return '';
    }

    const pluginUrl = (window.Themeasy && window.Themeasy.pluginUrl) ? window.Themeasy.pluginUrl : '';
    const src       = pluginUrl + 'assets/media/svg/' + parsed[0] + '/' + parsed[1] + '.svg';
    const imgAttrs  = Object.assign({ src: src, alt: '' }, attrs || {});

    return '<img' + window.Themeasy.htmlAttributesToString(imgAttrs) + ' />';
  };

  /**
   * Build an HTML attribute string from a plain object.
   *
   * Differs from htmlAttributes() in that it returns a leading space and
   * accepts boolean true/numeric values (coerced to string). Skips empty,
   * null, false, undefined. Same escaping contract as htmlAttributes():
   * names normalized to a safe subset, values entity-escaped (esc_attr()
   * parity) — pass raw, unescaped values.
   *
   * @param {Object} attributes
   * @returns {string}
   */
  window.Themeasy.htmlAttributesToString = function (attributes) {
    if (!attributes || typeof attributes !== 'object') {
      return '';
    }

    let out = '';

    Object.keys(attributes).forEach(function (key) {
      let value = attributes[key];
      if (Array.isArray(value)) {
        value = value.join(' ');
      }
      if (value === '' || value === null || value === undefined || value === false) {
        return;
      }
      const safeKey   = String(key).replace(/[^a-z0-9:_-]/gi, '');
      if (!safeKey) {
        return;
      }
      const safeValue = escapeAttribute(value);
      out += ' ' + safeKey + '="' + safeValue + '"';
    });

    return out;
  };

  /**
   * Manual icon fallback markup when elementor.helpers.renderIcon returns empty
   * (can happen on first widget insert).
   *
   * Supports:
   * - Themeasy inline SVGs: iconObj.library === 'themeasy-svg'
   * - Font icons: iconObj.value is a class string
   * - SVG icons: iconObj.value is an object { url: '...' }
   *
   * @param {Object} iconObj
   * @param {Object} attrs
   * @returns {string}
   */
  window.Themeasy.manualIconMarkup = function (iconObj, attrs) {
    if (!iconObj || !iconObj.value) {
      return '';
    }

    const safeAttrs = attrs || {};

    // Themeasy Icons picker tabs (ty-feather, ty-solar-*): inline first
    // (frontend parity), then <img> fallback when not preloaded.
    if (typeof iconObj.library === 'string' && iconObj.library.indexOf('ty-') === 0
        && typeof iconObj.value === 'string') {
      return window.Themeasy.tyIconInlineMarkup(iconObj.library, iconObj.value, safeAttrs)
          || window.Themeasy.tyIconImgMarkup(iconObj.library, iconObj.value, safeAttrs);
    }

    // Themeasy inline SVG from the plugin assets folder: try preloaded inline
    // first (matches frontend rendering — CSS color/stroke/fill work live in
    // the editor preview), then fall back to <img> when not preloaded.
    if (iconObj.library === 'themeasy-svg' && typeof iconObj.value === 'string') {
      return window.Themeasy.themeasySvgInlineMarkup(iconObj.value, safeAttrs)
          || window.Themeasy.themeasySvgImgMarkup(iconObj.value, safeAttrs);
    }

    // SVG icon: { value: { url: '...' }, library: 'svg' }
    if (typeof iconObj.value === 'object' && iconObj.value.url) {
      const imgAttrs = Object.assign({ src: iconObj.value.url, alt: '' }, safeAttrs);
      return '<img' + window.Themeasy.htmlAttributesToString(imgAttrs) + ' />';
    }

    // Font icon: value is class string. Merge font class into the class attribute.
    if (typeof iconObj.value === 'string') {
      const fontClass = String(safeAttrs.class || '').trim() + ' ' + iconObj.value;
      const fontAttrs = Object.assign({}, safeAttrs, { class: fontClass.trim() });
      return '<i' + window.Themeasy.htmlAttributesToString(fontAttrs) + '></i>';
    }

    return '';
  };

  /**
   * Best-effort icon renderer for Elementor editor:
   * 1) elementor.helpers.renderIcon (best compatibility)
   * 2) manual fallback using iconObj.value (reliable on first insert)
   *
   * Inline-SVG libraries ('themeasy-svg' and Media Library 'svg') never go
   * through Elementor's renderer output as-is: for svg markup it drops the
   * attributes argument entirely, which would diverge from the PHP side
   * (themeasy_render_icon_html injects attributes + the 1em normalization).
   * Keep both renderers byte-identical — this is the icon contract.
   *
   * Usage inside content_template():
   * Themeasy.renderIconMarkup(view, settings.my_icon, fallback, {});
   *
   * @param {Object} view Elementor view (from content_template scope)
   * @param {*} iconSetting Icon control setting
   * @param {Object|null} fallbackIcon Icon fallback object
   * @param {Object} attrs HTML attributes
   * @returns {string}
   */
  window.Themeasy.renderIconMarkup = function (view, iconSetting, fallbackIcon, attrs) {
    const iconObj = window.Themeasy.normalizeIconSetting(iconSetting, fallbackIcon);

    if (!iconObj) {
      return '';
    }

    const safeAttrs = attrs || {};
    const helpersReady = window.elementor && window.elementor.helpers
      && typeof window.elementor.helpers.renderIcon === 'function';

    // Themeasy inline SVG ('themeasy-svg' + the ty-* picker tabs): Elementor's
    // renderIcon would emit a font-icon <i> for these custom libraries — resolve
    // them directly via the manual markup builder so the preview matches the
    // frontend's inline SVG byte-for-byte (icon contract).
    if (iconObj.library === 'themeasy-svg'
        || (typeof iconObj.library === 'string' && iconObj.library.indexOf('ty-') === 0)) {
      const markup = window.Themeasy.manualIconMarkup(iconObj, safeAttrs);

      // Non-preloaded ty-* library (the Solar sets): manualIconMarkup fell
      // back to the transient <img> — kick a one-time background fetch that
      // caches the inline SVG and re-renders the view (mirrors Elementor's
      // own attachment flow below).
      if (typeof iconObj.library === 'string' && iconObj.library.indexOf('ty-') === 0
          && typeof iconObj.value === 'string' && markup.indexOf('<img') === 0) {
        requestTyIconSvg(iconObj.library, iconObj.value, view);
      }

      return markup;
    }

    // Media Library SVG: let Elementor fetch + cache the attachment (it
    // re-renders the view once the file arrives), then apply the same
    // attribute injection + normalization as PHP. While the fetch is still
    // pending, fall back to an <img> so the node keeps its footprint.
    if (iconObj.library === 'svg' && iconObj.value && typeof iconObj.value === 'object') {
      let svgMarkup = '';

      if (helpersReady) {
        const fetched = window.elementor.helpers.renderIcon(view, iconObj, safeAttrs, 'i', 'object');
        if (fetched && typeof fetched.value === 'string') {
          svgMarkup = fetched.value;
        }
      }

      if (svgMarkup && svgMarkup.indexOf('<svg') !== -1) {
        return window.Themeasy.injectSvgAttributes(svgMarkup, normalizeIconSvgAttributes(safeAttrs));
      }

      return window.Themeasy.manualIconMarkup(iconObj, safeAttrs);
    }

    // If Elementor isn't available yet for any reason, fallback.
    if (!helpersReady) {
      return window.Themeasy.manualIconMarkup(iconObj, safeAttrs);
    }

    const iconHtml = window.elementor.helpers.renderIcon(
      view,
      iconObj,
      safeAttrs,
      'i',
      'object'
    );

    if (iconHtml && iconHtml.value) {
      return iconHtml.value;
    }

    return window.Themeasy.manualIconMarkup(iconObj, safeAttrs);
  };

})(window);
